fn retry_attempt(
    public:Public<'_>,
    compiled:&PoolV1PairForestMergedC1CompilationV1,
    variant:Variant,
    hash:HashFn,
    nonce_store:&mut DurableStateOnlyMaskNonceStore,
    mut next_attempt:impl FnMut(usize)->Result<StateOnlyAttemptSecrets,Error>,
    k:usize,
)->Result<RetriedProof,Error> {
    if k>=ATTEMPT_CAP { return Err(Error::AttemptsExhausted); }
    let attempt=next_attempt(k)?;
    match prove_masked_attempt(public,compiled,variant,hash,attempt,nonce_store) {
        Ok((proof,audit))=>Ok(RetriedProof{proof,audit,attempts:k+1}),
        Err(Error::Rejected)=>retry_attempt(public,compiled,variant,hash,nonce_store,next_attempt,k+1),
        Err(e)=>Err(e),
    }
}

fn semantic_error(e:SError)->Error {
    #[cfg(feature="r1p-check")]
    if e==SError::ActivePole { return Error::Rejected; }
    let _=e;
    Error::Semantic
}

fn mask_error(e:StateOnlyMaskBuildError)->Error {
    #[cfg(feature="r1p-check")]
    if e==StateOnlyMaskBuildError::MaskSampleExhausted { return Error::Rejected; }
    let _=e;
    Error::Semantic
}

pub fn prove_for_proof_accounts(
    public: Public<'_>,
    compiled: &PoolV1PairForestMergedC1CompilationV1,
    hash: HashFn,
    nonce_store: &mut DurableStateOnlyMaskNonceStore,
    mut proof_account: impl FnMut(usize) -> [u8; 32],
) -> Result<RetriedProof, Error> {
    prover::prove_masked_retrying_with(public, compiled, Variant::S2, hash, nonce_store, |k| {
        StateOnlyAttemptSecrets::generate_for_mask_nonce(proof_account(k)).map_err(|_| Error::Entropy)
    })
}

fn main()->Result<()> {
 let mut s=String::new();io::stdin().read_to_string(&mut s)?;let q:Value=serde_json::from_str(&s)?;
 if q.get("action").is_some(){println!("{}",plan::run(&q)?);return Ok(())}
 let keys:Vec<Keypair>=q["keys"].as_array().unwrap().iter().map(|p|{let b:Vec<u8>=serde_json::from_slice(&fs::read(p.as_str().unwrap()).unwrap()).unwrap();Keypair::try_from(b.as_slice()).unwrap()}).collect();
 let ixs:Vec<Instruction>=q["instructions"].as_array().unwrap().iter().map(|i|Instruction{program_id:Address::from_str(i["program"].as_str().unwrap()).unwrap(),accounts:i["accounts"].as_array().unwrap().iter().map(|a|AccountMeta{pubkey:Address::from_str(a[0].as_str().unwrap()).unwrap(),is_signer:a[1].as_bool().unwrap(),is_writable:a[2].as_bool().unwrap()}).collect(),data:unhex(i["data"].as_str().unwrap())}).collect();
 let conf=TransactionConfig::empty().with_priority_fee(10000).with_compute_unit_limit(1_400_000).with_loaded_accounts_data_size_limit(8*1024*1024).with_heap_size(256*1024);
 let m=Message::try_compile_with_config(&keys[0].pubkey(),&ixs,q["blockhash"].as_str().unwrap().parse()?,conf)?;
 let refs:Vec<&Keypair>=keys.iter().collect();let tx=VersionedTransaction::try_new(VersionedMessage::V1(m),&refs)?;
 let b=wincode::serialize(&tx)?;ensure!(b.len()<=4096,"TxV1 exceeds 4096 bytes");
 println!("{}",serde_json::json!({"hex":hex(&b),"signature":tx.signatures[0].to_string(),"bytes":b.len()}));Ok(())
}

